    placeholder,
    disabled,
    className,
    "data-testid": dataTestId
  }: any) => (
    <input
      value={value ?? ""}
      onChange={(event) => onChange?.(event)}
      placeholder={placeholder}
      disabled={disabled}
      className={className}
      data-testid={dataTestId}
    />
  )
  InputComponent.TextArea = ({
    value,
    onChange,
    placeholder,
    readOnly,
    disabled,
    className,
    "data-testid": dataTestId
  }: any) => (
    <textarea
      value={value ?? ""}
      onChange={(event) => onChange?.(event)}
      placeholder={placeholder}
      readOnly={readOnly}
      disabled={disabled}
      className={className}
      data-testid={dataTestId}
    />
  )

  const SelectComponent = ({
    value,
    options = [],
    onChange,
    disabled,
    ...rest
  }: any) => (
    <select
      value={value ?? ""}
      onChange={(event) => onChange?.(event.target.value)}
      disabled={disabled}
      {...rest}
    >
      {Array.isArray(options)
        ? options.map((option: any) => (
            <option
              key={String(option?.value)}
              value={String(option?.value || "")}
            >
              {typeof option?.label === "string"
                ? option.label
                : String(option?.value || "")}
            </option>
          ))
        : null}
    </select>
  )

  return {
    Button: ({
      children,
      onClick,
      disabled,
      loading,
      htmlType,
      className,
      title,
      "aria-label": ariaLabel
    }: any) => (
      <button
        type={htmlType || "button"}
        onClick={onClick}
        disabled={disabled || loading}
        className={className}
        title={title}
        aria-label={ariaLabel}
      >
        {children}
      </button>
    ),
    Checkbox: ({ children, checked, onChange, disabled }: any) => (
      <label>
        <input
          type="checkbox"
          checked={Boolean(checked)}
          onChange={(event) => onChange?.(event.target.checked)}
          disabled={disabled}
        />
        {children}
      </label>
    ),
    Dropdown: ({ children }: any) => <>{children}</>,
    Input: InputComponent,
    InputNumber: ({ value, onChange, disabled }: any) => (
      <input
        type="number"
        value={value ?? ""}
        onChange={(event) => onChange?.(Number(event.target.value))}
        disabled={disabled}
      />
    ),
    Radio: {
      Group: ({ children, value, onChange }: any) => (
        <div data-value={value} onChange={onChange}>
          {children}
        </div>
      ),
      Button: ({ children }: any) => <button type="button">{children}</button>
    },
    Select: SelectComponent,
    Switch: ({ checked, onChange }: any) => (
      <button type="button" aria-pressed={checked} onClick={() => onChange?.(!checked)}>
        switch
      </button>
    ),
    Tooltip: ({ children }: any) => <>{children}</>,
    Modal: Object.assign(
      ({
        open,
        children
      }: {
        open?: boolean
        children: React.ReactNode
      }) => (open ? <div data-testid="modal">{children}</div> : null),
      {
        confirm: vi.fn()
      }
    )
  }
})

